} end)()
t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["Back to the {area:228}"] = "Вернитесь в {area:228}",
		["Free her with the key, then stay close while she fights her way out of the keep."] = "Освободите ее ключом и держитесь рядом, пока она пробивается из крепости.",
		["Free {npc:248755}"] = "Освободите {npc:248755}",
		["No item yet: a Forsaken paladin rescue story; its sequel, the {item:268484}, cannot be finished yet."] = "Предмета пока нет: история о спасении для паладина Отрекшихся; ее продолжение, {item:268484}, пока нельзя завершить.",
		["Once she is clear of {area:235}, {npc:259620} waits for you in the {area:228}. Speak with her again to hear what really happened on the road."] = "Когда она выберется из места {area:235}, {npc:259620} ждет вас в месте {area:228}. Поговорите с ней снова, чтобы узнать, что на самом деле случилось в дороге.",
		["Rescuing {quest:91862}"] = "Спасение: {quest:91862}",
		["Ride south through {zone:1421} to the {area:228}. {npc:248840} stands in the town; {npc:259611} keeps watch near its entrance."] = "Езжайте на юг через {zone:1421} к {area:228}. {npc:248840} стоит в поселении; {npc:259611} стоит на страже у входа.",
		["The pyre on {area:172}"] = "Погребальный костер: {area:172}",
		["from the {object:566037}"] = "Объект: {object:566037}",
		["{area:172} lies in the lake east of the {area:228}. The charred remains are on its shore."] = "{area:172} — остров в озере к востоку от {area:228}. Обугленные останки лежат на его берегу.",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412} – с гноллов из стаи Гнилошкуров",
		["{npc:246378} leads the Paladins of Tyr's Watch from inside {area:16602}, on the bluffs north-west of the {area:156}."] = "{npc:246378} руководит паладинами Tyr's Watch изнутри места {area:16602}, на утесах к северо-западу от места {area:156}.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, {area:228}",
		["{quest:91862} is caged inside {area:235}, at the north end of the isle. The Rot Hide gnolls around her carry the key."] = "{quest:91862} заперта в клетке здесь: {area:235}, северный край острова. Ключ у гноллов из стаи Гнилошкуров вокруг нее.",
		["{zone:1458} and Earthen Ring reputation"] = "Репутация: {zone:1458} и Служители Земли",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "Назад в крепость",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "Назад. Цель: {area:16602}. {npc:246378} даст вам {item:6866}; {npc:257655} ждет внизу в крепости.",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "Назад. Цель: {area:16602}. Билмут примет планы, {npc:246378} научит вас: {spell:7328}.",
		["Tarnished Drudges"] = "Порочные чернорабочие",
		["Tarnished Zealots"] = "Порочные фанатики",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "Планы атаки – у крестоносцев Алого ордена, стоящих лагерем вокруг места {area:812}.",
		["The Scarlet attack plans"] = "Планы атаки Алого ордена",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "Мурлоки из племени Злобного Плавника скрываются на утесах вдоль дороги к востоку от крепости и в лагерях вокруг озера к западу.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Дозор Тира и {spell:7328}",
		["Vile Fin Attackers"] = "Налетчики из племени Злобного Плавника",
		["Vile Fin Seers"] = "Провидцы из племени Злобного Плавника",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Идите на юг от места {area:159}. Цель: {area:153}; спуститесь в {zone:1458}. {npc:10181} принимает здесь: {object:36126}; {npc:257648} попрошайничает здесь: {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602} стоит на утесах к северо-западу (ориентир: {area:156}). {npc:246349} ждет у ворот.",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812} – в дальнем восточном конце лесов. Используйте {item:6866} на цели {npc:257663}, затем поговорите с ним. Если потеряете символ, {npc:246378} даст новый.",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "{npc:246152}, учитель паладинов ({area:159}), отправит вас в крепость ордена на западном побережье.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378} руководит орденом из крепости; {npc:246393} стоит рядом с ней.",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378} дает первый урок божественности на 12-м уровне.",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648} нужно 10 шт.: {item:2589}. С ревнителей и келейников из Алого ордена она падает примерно в трех случаях из десяти; если у вас уже есть, захватите с собой.",
		["{object:554626}, in the root cellar"] = "{object:554626}, в погребе",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317}: они занимают разрушенную деревню ({area:16881}, {area:16616}) к юго-западу от крепости. {item:246213} сложены в погребе одного из домов; среди своих порочных ходит командир {npc:259431}.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328} для воскрешения павших союзников, а также оружие и щит для нового паладина-Отрекшегося.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "На 20-м уровне {npc:6179} ({object:32362}) дает вам {item:6776}; он отправляет вас к NPC {npc:6171} в Собор Света ({zone:1453}). Сядьте на подземный поезд из города {zone:1455} в город {zone:1453}.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Вернитесь к {npc:3649} ({area:442}): он очистит самоцвет.",
		["Back to {npc:6241}"] = "Обратно к NPC {npc:6241}",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "Отнесите четыре части NPC {npc:6181} у ворот города {zone:1455}.",
		["Goblin Woodcarvers, inside"] = "Гоблины-древорубы, внутри",
		["Protect {npc:6182}"] = "Защитите: {npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "Редкая двуручная булава паладина Альянса для уровней 20-29, а по пути еще и щит.",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "Наги Непроглядной Пучины у входа в {area:2797} на северо-западном побережье зоны {zone:1440} оставляют {item:6995}. Они элитные: лучше собрать группу.",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "Ящик с рудой лежит у деревьев посреди лагеря огров Мо'Грош на северо-востоке зоны {zone:1432}. Огры Мо'Грош — элитные: лучше собрать группу.",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["from the {item:6776}"] = "из предмета {item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581} — подземелье для группы из пяти игроков под деревней {area:20}; портал подземелья — внутри шахты ({area:20}). Гоблины-древорубы в корабельном зале, где Снид, оставляют древесину.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, в шахте ({area:20})",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236} — подземелье для уровней 20-30 на юге зоны {zone:1421}. Молот лежит на ящике в конюшне, в дальнем конце двора перед подъемом по пандусу.",
		["{npc:3649} is in {area:442}."] = "{npc:3649} находится здесь: {area:442}.",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171} стоит в Соборе Света. Щелкните правой кнопкой мыши по предмету {item:6776}, чтобы начать его задание.",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181} стоит у ворот города {zone:1455}. Он дает вам {item:6996}, где перечислены четыре части.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "Ферма NPC {npc:6182} стоит на юго-западном побережье зоны {zone:1436}. Во время ее задания на ферму нападают волны Братства Справедливости: не дайте ей погибнуть и лечите ее при необходимости.",
		["{npc:6241} is in {area:144}."] = "{npc:6241} находится здесь: {area:144}.",
		["{npc:6241} turns the ore into {item:6993}."] = "{npc:6241} превращает руду в {item:6993}.",
		["{object:91138}, inside"] = "{object:91138}, внутри",
		["{object:92420} crate"] = "Ящик: {object:92420}",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646} to see {npc:14494}, a ghost on the mountainside in the north-west of the {zone:1423}. Come with full mana, Major Mana Potions and {item:8956}: if you fail, the event takes about two hours to return."] = "Наденьте {item:18646}, чтобы увидеть NPC {npc:14494} — призрака на склоне горы на северо-западе зоны {zone:1423}. Приходите с полной маной, запасом хороших зелий маны и предметом {item:8956}: при провале событие возвращается примерно через два часа.",
		["Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with {spell:139}. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone."] = "Спасите 50 крестьян, пока не погибли 15. Убивайте нападающих на них скелетов, лечите их болезни (сначала фиолетовые) и исцеляйте раненых заклинанием «{spell:139}». Друзья могут наложить на вас бафы заранее, но должны держаться вне боя, иначе появится демон и убьет всех.",
		["With both Eyes in your bags: {item:18608}"] = "С обоими Оками в сумках: {item:18608}",
		["You need {item:18646} first: it comes from the {object:179703} after {npc:12018} in {area:2717}. {item:18665} drops from elite demons ({npc:12397}, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too."] = "Сначала нужен предмет {item:18646}: он лежит в объекте {object:179703} после победы над NPC {npc:12018} ({area:2717}). {item:18665} падает с элитных демонов ({npc:12397}, мировой босс — всегда; стражники ужаса-командиры и гончие маны — редко); он становится персональным при надевании, так что его можно и купить.",
		["{item:18608} and Anathema"] = "{item:18608} и Анафема",
		["{npc:14494}'s splinter and the two Eyes make {item:18608}, the epic priest staff that turns into Anathema."] = "Осколок {npc:14494} и два Ока дают {item:18608}, эпический посох жреца, который превращается в Анафему.",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["Any undead can drop it. The {npc:7864} in the {area:1221}, below {npc:8405}'s cliffs, are the nearest; Highborne Apparitions and Lichlings haunt the ruins near {area:3137}."] = "Она может выпасть с любой нежити. Ближе всего — {npc:7864} в месте {area:1221}, под скалами, где живет {npc:8405}; тени высокорожденных и призраки высокорожденных бродят по руинам у места {area:3137}.",
		["At 50 {npc:5489} in {zone:1453}'s Cathedral of Light or {npc:11406} in {zone:1455}'s {object:32386} offers it."] = "На 50-м уровне его дает {npc:5489} (Собор Света, {zone:1453}) или {npc:11406} ({zone:1455}, {object:32386}).",
		["At 50 {npc:6018} in {zone:1454}'s {object:172961} offers it."] = "На 50-м уровне его дает {npc:6018} ({zone:1454}, {object:172961}).",
		["Experience and gold"] = "Опыт и золото",
		["Experience and gold at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Опыт и золото на 50-м уровне через зону {zone:1447} и {area:1417}; Forever убрал выбор предмета из классики.",
		["Morphaz in the {area:1417}"] = "Морфаз — {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Морфаз — элитный босс-дракон внутри подземелья {area:1417} (уровень 50): соберите группу из пяти. Храм стоит посреди места {area:74}; нырните вниз, чтобы добраться до входа. Орда: летите в {area:75}; Альянс: летите в {area:42} или {area:1438} и езжайте дальше.",
		["Mosshoof Coursers graze all over {zone:1447}; about one in three drops a {item:20027}."] = "Мохоногие олени пасутся по всей зоне {zone:1447}; примерно с каждого третьего падает {item:20027}.",
		["{npc:10922} is at the {area:2479} in southern {zone:1448}."] = "{npc:10922} находится здесь: {area:2479}, юг зоны {zone:1448}.",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} живет на вершине скал к северо-востоку от места {area:1221}. Альянс: летите в {area:3137}; Орда: летите в {area:1237}.",
		["{quest:8254} (Alliance)"] = "{quest:8254} (Альянс)",
		["{quest:8254} (Horde)"] = "{quest:8254} (Орда)",
		["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}: вход ({area:1417})",
} end)()
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = (function() return {
		["At 10, go to {npc:258785} in the {object:32386}, in {zone:1455}'s {object:32362}. {npc:1226} in {area:131}, {npc:377} in {area:87} and {npc:376} in {zone:1453} send you to her with a quest of the same name (its text may say {zone:1453}: Mims is in {zone:1455})."] = "На 10-м уровне идите к NPC {npc:258785} ({object:32386}, {object:32362}, {zone:1455}). {npc:1226} ({area:131}), {npc:377} ({area:87}) и {npc:376} ({zone:1453}) отправляют вас к ней с одноименным заданием (в его тексте может быть указан город {zone:1453}: Мимс находится в городе {zone:1455}).",
		["At 20, {npc:258785} teaches {quest:94818}. {npc:376} in {zone:1453} sends you to her with a quest of the same name."] = "На 20-м уровне {npc:258785} обучает заклинанию {quest:94818}. {npc:376} ({zone:1453}) отправляет вас к ней с одноименным заданием.",
		["The Gnome priest spells, new in Forever: one at 10, one at 20."] = "Заклинания жрецов-гномов, новые в Forever: одно на 10-м уровне, другое на 20-м.",
		["{quest:94817} and {quest:94818}"] = "{quest:94817} и {quest:94818}",
} end)()
t.guides["forever/class/priest/desperate-prayer-and-chastise"] = (function() return {
		["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362}. Forever's quest text names Rohan, but the quest data has {npc:376} in {zone:1453}'s Cathedral of Light take it: try Rohan first, then Laurena (the {area:2257} links the cities)."] = "На 10-м уровне идите к NPC {npc:11406} ({object:32386}, {zone:1455}, {object:32362}). В тексте задания Forever назван Рохан, но по данным задания его принимает {npc:376} (Собор Света, {zone:1453}): сначала попробуйте Рохана, затем Лорену (города связывает {area:2257}).",
		["At 20, {npc:11406} teaches {quest:5641}. {npc:376} in {zone:1453} and {npc:11401} in {zone:1457} send you to him with a quest of the same name."] = "На 20-м уровне {npc:11406} обучает заклинанию {quest:5641}. {npc:376} ({zone:1453}) и {npc:11401} ({zone:1457}) отправляют вас к нему с одноименным заданием.",
		["If Rohan did not take it: {npc:376} is in the Cathedral of Light. Take the {area:2257} from {object:171524}."] = "Если Рохан не принял задание: {npc:376} — в Соборе Света. Поезжайте на поезде ({area:2257}) из места {object:171524}.",
		["The Human and Dwarf priest spells: {quest:5634} at 10, {quest:5641} for Dwarves at 20."] = "Заклинания жрецов-людей и дворфов: {quest:5634} на 10-м уровне, {quest:5641} для дворфов на 20-м.",
		["{quest:5634} and {quest:5641}"] = "{quest:5634} и {quest:5641}",
} end)()
t.guides["forever/class/priest/divine-grace-and-feedback"] = (function() return {
		["At 10, go to {npc:376} in the Cathedral of Light. {npc:377} in {area:87} sends you to her with a quest of the same name."] = "На 10-м уровне идите в Собор Света. Цель: {npc:376}. {npc:377} ({area:87}) отправит вас к ней с одноименным заданием.",
		["At 20, {npc:376} teaches {spell:13896}. {npc:11406} in {zone:1455} and {npc:11401} in {zone:1457} send you to her with a quest of the same name."] = "На 20-м уровне {npc:376} обучает: {spell:13896}. {npc:11406} ({zone:1455}) и {npc:11401} ({zone:1457}) отправят вас к ней с одноименным заданием.",
		["The Human priest spells: {quest:94773} at 10, {spell:13896} at 20."] = "Заклинания жрецов-людей: {quest:94773} на 10-м уровне, {spell:13896} на 20-м.",
		["{quest:94773} and {spell:13896}"] = "{quest:94773} и {spell:13896}",
} end)()
t.guides["forever/class/priest/hex-of-weakness-and-shadowguard"] = (function() return {
		["At 10, go to {npc:6018} in the {object:172961}, on {zone:1454}'s west side. Priest trainers elsewhere ({npc:3706} in {area:362}, {npc:3044} in {zone:1456}) send you to him with a quest of the same name."] = "На 10-м уровне идите к NPC {npc:6018} ({object:172961}, западная часть города {zone:1454}). Учителя жрецов в других местах ({npc:3706} — {area:362}, {npc:3044} — {zone:1456}) отправляют вас к нему с одноименным заданием.",
		["At 20, {npc:6018} teaches {quest:5642}. {npc:3044} in {zone:1456} and Aelthalyste in the {zone:1458} send you to him with a quest of the same name."] = "На 20-м уровне {npc:6018} обучает заклинанию {quest:5642}. {npc:3044} ({zone:1456}) и Эльталисте ({zone:1458}) отправляют вас к нему с одноименным заданием.",
		["The Troll priest spells: {quest:5652} at 10, {quest:5642} at 20."] = "Заклинания жрецов-троллей: {quest:5652} на 10-м уровне, {quest:5642} на 20-м.",
