t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165}, in the north of {zone:1455}."] = "На 16-м уровне {npc:1234} ({area:2102}, {area:131}) отправляет вас к NPC {npc:5165} на севере города {zone:1455}.",
		["At 16 {npc:3599} in {area:186} sends you to {quest:2259} in {zone:1457}."] = "На 16-м уровне {npc:3599} ({area:186}) отправляет вас к NPC {quest:2259} ({zone:1457}).",
		["At 16 {npc:917}, the rogue trainer in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}."] = "На 16-м уровне {npc:917}, учитель разбойников в таверне «Гордость льва» ({area:87}), отправляет вас к NPC {npc:6946} ({zone:1453}).",
		["Back to {npc:6966}"] = "Вернитесь: {npc:6966}",
		["Ride east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} waits on the west side of {area:69} and gives you {item:5060}."] = "Езжайте на восток через {zone:1429} в Красногорье или летите в {area:69}. {npc:6966} ждет на западной окраине места {area:69} и дает вам предмет: {item:5060}.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Ваше первое задание по вскрытию замков на 16-м уровне: сундучок (владелец — {npc:6966}) у места {quest:2282}, для {quest:2300}.",
		["{npc:6946} stands beside {npc:332} at {quest:2300} in {object:2100}. Dwarves and Gnomes take the {area:2257} from {zone:1455}; Night Elves take the boat from {area:442} to {area:17203}."] = "{npc:6946} стоит рядом с NPC {npc:332} в {quest:2300} ({object:2100}). Дворфы и гномы едут на поезде ({area:2257}) из города {zone:1455}; ночные эльфы плывут на корабле из места {area:442} в {area:17203}.",
		["{quest:2282} stands east of {area:69}, up off the road. Open {object:121264} there."] = "{quest:2282} — к востоку от места {area:69}, выше дороги. Откройте там: {object:121264}.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "На 16-м уровне {npc:3170}, учитель разбойников ({area:362}), отправляет вас к персонажу {npc:3401} ({zone:1454}).",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "На 16-м уровне {npc:6467} ({object:36073}) отправляет вас к персонажу {npc:3401} ({zone:1454}). Возьмите у него и задание «{quest:1998}»; оно выполняется в конце этого гайда ({zone:1421}).",
		["Back to {npc:6467}"] = "Назад к {npc:6467}",
		["Back to {npc:7161}"] = "Назад к {npc:7161}",
		["Fly or ride to {area:392} on the {zone:1413} coast. {npc:7161} stands in town with his Gizmotronic Apparatus: buy an {item:7970} and {item:5060} from the apparatus before you go."] = "Летите или езжайте сюда: {area:392} – на побережье ({zone:1413}). {npc:7161} стоит в городе со своим гизмотронным аппаратом: перед уходом купите у аппарата {item:7970} и {item:5060}.",
		["South along the coast from {area:392}, at the Southsea pirates' camp. If an unusually hostile parrot attacks you, use the {item:7970} on it (the quest's own advice)."] = "К югу вдоль побережья от места {area:392}, в лагере пиратов Южных морей. Если на вас нападет необычно враждебный попугай, используйте на нем {item:7970} (совет из самого задания).",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south into Silverpine. {quest:1998} stands north-east of the {area:228}."] = "Летите на дирижабле: {zone:1454} → {zone:1458}, затем езжайте на юг, в Серебряный бор. {quest:1998} стоит к северо-востоку от места {area:228}.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Десять шт. {item:7676} – энергетического напитка разбойников – за задания Орды по взлому замков на 16-м уровне.",
		["The Kirin Tor keep their reports at {area:233}, in south-east Silverpine: pick the lock on the {object:103815}."] = "Кирин-Тор хранит свои донесения здесь: {area:233}, юго-восток Серебряного бора. Взломайте замок: {object:103815}.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}."] = "Нежить летит на дирижабле от башен за пределами города ({zone:1458}) сюда: {zone:1411}. {npc:3401} и {quest:2379} стоят здесь: {object:172960} – ущелье под местом {object:172982}.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} и {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: десять шт. {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay down"] = "/lay down",
		["At 20 {npc:332} at SI:7 in {object:2100} sends you to {npc:7024} in {zone:1436}."] = "На 20-м уровне {npc:332} (ШРУ, {object:2100}) отправляет вас к персонажу {npc:7024} ({zone:1436}).",
		["Back to {npc:7207}"] = "Назад: {npc:7207}",
		["Everything is in {zone:1453}: the Gumps sell {item:3421}, the {item:8431} lies in the city, and the nearest vendors sell a {item:3372} and a {item:4371}."] = "Все есть в городе {zone:1453}: {item:3421} продают Гампы, {item:8431} лежит в городе, а {item:3372} и {item:4371} продают ближайшие торговцы.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever навыку «{spell:2842}» учит эта цепочка, а не учитель; вместе с ним вы получите рецепт: {item:7676}.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Езжайте на север через Элвиннский лес: {zone:1453}. Мастер Матиас Шоу – в здании ШРУ ({object:2100}).",
		["The cure's ingredients"] = "Ингредиенты лекарства",
		["{item:7908}, in the {object:123214}"] = "{item:7908}: {object:123214}",
		["{npc:7024} watches {npc:7053}'s tower from the hills in the far east of {zone:1436}, by the {zone:1431} border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "{npc:7024} следит за башней ({npc:7053}) с холмов на дальнем востоке зоны {zone:1436}, у границы зоны {zone:1431}. Ключ от башни у ее охранника – {npc:7051} (23-й уровень); дневник Клавена – в сундуке наверху.",
		["{npc:7207} works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined."] = "{npc:7207} работает в подвале здания ШРУ (казармы). Введите /lay down рядом с ним, чтобы он вас осмотрел.",
		["{spell:2842} (Alliance)"] = "{spell:2842} (Альянс)",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salute: {npc:3401}",
		["At 20 {npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Target him and type /salute."] = "На 20-м уровне {npc:3401} стоит здесь: {object:172960} — ущелье под местом {object:172982}. Выберите его целью и введите /salute.",
		["Back to {npc:3401}"] = "Вернитесь: {npc:3401}",
		["Fly back to {zone:1454}."] = "Летите обратно в город {zone:1454}.",
		["Fly to the {area:380} and ride north to the Venture Co. tower north of the {area:382}. In sight of the tower, fire the {item:8051} twice, then /salute {npc:7233} before he attacks you."] = "Летите сюда: {area:380}. Скачите на север к башне Торговой компании севернее места {area:382}. В пределах видимости башни выстрелите из ракетницы ({item:8051}) дважды, затем выполните /salute для NPC {npc:7233}, пока он не напал на вас.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever {spell:2842} изучаются через эту цепочку, а не у учителя; заодно вы получаете рецепт: {item:7676}.",
		["Stay stealthed. {npc:7287} carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it."] = "Оставайтесь в незаметности. У NPC {npc:7287} ключ от башни; Нервотреп (элитный) и его сундучок — на вершине башни. Убейте по двое мертвяков, патрульных и наблюдателей Торговой компании вокруг нее.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south through {zone:1421} to {area:272} in {area:287}. {npc:2391} stands in {area:272}; wait beside him while he brews the cure."] = "Сядьте на дирижабль из города {zone:1454} в город {zone:1458} и скачите на юг через зону {zone:1421} сюда: {area:272} ({area:287}). {npc:2391} стоит здесь: {area:272}; подождите рядом, пока он варит лекарство.",
		["Wait for the cure"] = "Дождитесь лекарства",
		["{item:8051}, twice, in sight of the tower"] = "{item:8051}: дважды, в пределах видимости башни",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (элитный)",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: сохраните {item:8051}",
		["{spell:2842} (Horde)"] = "{spell:2842} (Орда)",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 an {item:17126} from {npc:13936} starts this; the data gives it to you through {npc:332} or {npc:918} in {zone:1453}, or Gest or Ormok in {zone:1454}. The quest hands you the {item:17125} for {npc:6707}."] = "На 24-м уровне все начинается с предмета {item:17126} ({npc:13936}); по данным его вручает {npc:332} или {npc:918} ({zone:1453}), либо Гест или Ормок ({zone:1454}). Задание дает вам {item:17125} для персонажа {npc:6707}.",
		["At 36, {npc:13085} sends you after Barton's scouting report. Barton leads a Syndicate party at {area:280}, in the east of the {zone:1416}: pick his pocket, do not kill him."] = "На 36-м уровне {npc:13085} отправляет вас за разведдонесением Бартона. Бартон возглавляет отряд Синдиката здесь: {area:280}, восток зоны {zone:1416}. Обчистите его карманы, не убивайте.",
		["Back to {npc:13085}"] = "Назад к {npc:13085}",
		["Horde fly to {area:272}, Alliance to {area:271}. The manor hides in the hills east of {area:272}, up a path into the {zone:1416}; the Rite of Cunning is passing its way in."] = "Орда летит сюда: {area:272}, Альянс – сюда: {area:271}. Поместье скрыто в холмах к востоку от места {area:272}, вверх по тропе в зону {zone:1416}; чтобы войти, пройдите обряд хитрости.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and its first jobs."] = "Открывает {area:3486} – тайный дом разбойников в холмах Альтерака – и первые поручения.",
		["Rite of Cunning"] = "Обряд хитрости",
		["The {item:17126}"] = "{item:17126}",
		["{item:275482}: pickpocket Barton"] = "{item:275482}: обчистите карманы Бартона",
		["{npc:13936} reputation"] = "Репутация: {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress in eastern {area:287}, south of the manor. Quick and quiet, says {npc:13085}."] = "{npc:266216} – внутри крепости Синдиката ({area:275}) на востоке зоны {area:287}, к югу от поместья. Быстро и тихо, говорит {npc:13085}.",
