t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. The Timbermaw Shamans in {zone:1447}'s northern hills drop the bag, about one in thirty."] = "Альянс летит сюда: {area:3137}, Орда – сюда: {area:1237}. Сумка падает с шаманов из племени Древобрюхов в северных холмах ({zone:1447}), примерно с одного из тридцати.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "На 50-м уровне его дает {npc:3328} ({object:172960}); а также {npc:4583} ({zone:1458}, {object:36073}).",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} and Fenthwick in {zone:1455}."] = "На 50-м уровне его дает {npc:918} ({zone:1453}, {object:2100}); а также Сиарна ({zone:1457}), {npc:5165} и Иззаспинс ({zone:1455}).",
		["Back to Xylem"] = "Назад к Ксилему",
		["Lord Ravenholdt"] = "Лорд Черный Ворон",
		["Morphaz in the {area:1417}"] = "Морфаз: {area:1417}",
		["Morphaz, a green drake, is an elite boss deep in the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the {area:74}; swim down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on."] = "Морфаз, зеленый дракон, – элитный босс в глубине подземелья 50-го уровня ({area:1417}): возьмите группу из пяти человек. Храм стоит здесь: {area:74}; спуститесь вплавь ко входу. Орда: летите сюда: {area:75}; Альянс: летите сюда: {area:1438} – и езжайте дальше.",
		["Ravenholdt reputation"] = "Репутация у Черного Ворона",
		["Ravenholdt reputation and experience at 50; Forever removed the Classic item choice."] = "Репутация у Черного Ворона и опыт на 50-м уровне; Forever убрал выбор предмета из Classic.",
		["The Forest Oozes of southern {zone:1447} drop the fragments."] = "Фрагменты падают с лесных слизнюков на юге зоны {zone:1447}.",
		["{area:3486} hides in the hills east of {area:272}, up a path into the {zone:1416}. Horde fly to {area:272}, Alliance to {area:271}."] = "{area:3486} скрыто в холмах к востоку от места {area:272}, вверх по тропе в зону {zone:1416}. Орда летит сюда: {area:272}, Альянс – сюда: {area:271}.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Морфаз, внутри храма",
		["{npc:6768}: no item choices in Forever"] = "{npc:6768}: в Forever выбора предмета нет",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Альянс)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Орда)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Вернитесь к тайнику",
		["C's dead drop"] = "Тайник C",
		["Find the Eye of Bhossca inside the {area:796}."] = "Найдите Глаз Бхосски внутри: {area:796}.",
		["Place the eye in the {object:410369} near Pyrewood. C's payment is the second Eye of Bhossca quest at the same chest."] = "Положите глаз сюда: {object:410369}, у Погребальных Костров. Плата от C – второе задание о Глазе Бхосски у того же сундука.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone; C advises a disguise from the monastery's grounds before you enter."] = "Монастырь стоит на крайнем северо-востоке зоны {zone:1420}. Идите один; C советует добыть маскировку на территории монастыря перед входом.",
		["The {area:796}"] = "Локация: {area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "{item:277246} — плата от C за одиночную работу внутри: {area:796}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. C's next note waits there once you are 25."] = "{object:410369} — сундук у места {area:204} на юге Серебряного бора, чуть южнее: {area:236}. Следующая записка C ждет там, когда вам исполнится 25 уровень.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Назад к тайнику",
		["C's dead drop"] = "Тайник C",
		["Go in alone. The {item:210186} gets you past the courtyard gate; the data does not say where in the keep the horn lies."] = "Входите в одиночку. {item:210186} пропустит вас через ворота двора; где в крепости лежит рог, данные не сообщают.",
		["Place the horn in the {object:410369} near Pyrewood. C's payment is the second {item:210183} quest at the same chest."] = "Положите рог в {object:410369} у Деревни Погребальных Костров. Плата от C – второе задание ({item:210183}) у того же сундука.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210} – плата от C за одиночную работу здесь: {area:236}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. Read C's note."] = "{object:410369} – сундук возле места {area:204} на юге Серебряного бора, чуть южнее места {area:236}. Прочитайте записку C.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, внутри ({area:236})",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers around him carry them."] = "{npc:4086}, гоблин, дружелюбный к обеим фракциям, стоит среди Торговой компании ({area:461}), на востоке Когтистых гор. Орда летит сюда: {area:460}; Альянс – сюда: {area:467}. Прежде чем отдать взрывчатку, он хочет {item:210187}: они есть у лесорубов Торговой компании вокруг него.",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}."] = "На 30-м уровне {npc:258098}, учитель шаманов ({zone:1455}), отправляет вас к персонажу {npc:259023} ({zone:1417}).",
		["The Lost Ones in the north of the {zone:1435} carry the Twisted Earth Totems."] = "Изуродованные тотемы земли носят Заблудшие на севере зоны {zone:1435}.",
		["The Maraudine centaurs of western {zone:1443} carry the Twisted Air Totems."] = "Изуродованные тотемы воздуха носят кентавры Мародин на западе зоны {zone:1443}.",
		["The Mirefin murlocs of northern {zone:1445} carry the Twisted Water Totems."] = "Изуродованные тотемы воды носят мурлоки из племени Болотного Плавника на севере зоны {zone:1445}.",
		["The Stonevault troggs in the south of the {zone:1418} carry the Twisted Fire Totems."] = "Изуродованные тотемы огня носят трогги из племени Каменного Свода на юге зоны {zone:1418}.",
		["The steam pools"] = "Паровые озера",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "{item:5178}, позволяющий ставить тотемы воздуха, затем оружие на выбор на 40-м уровне.",
		["Twisted Air Totems"] = "Изуродованные тотемы воздуха",
		["Twisted Earth Totems"] = "Изуродованные тотемы земли",
		["Twisted Fire Totems"] = "Изуродованные тотемы огня",
		["Twisted Water Totems"] = "Изуродованные тотемы воды",
		["{area:1717} is a dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} is its last boss. Bring a group."] = "{area:1717} – подземелье на южном краю зоны {zone:1413} (стрелка указывает на вход); {npc:4421} – его последний босс. Возьмите группу.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}: {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}: с персонажа {npc:4421}",
		["{npc:259023} camps in the northern hills of {zone:1417}."] = "{npc:259023} стоит лагерем в северных холмах зоны {zone:1417}.",
		["{npc:259023} hands you the {item:268582}: place them at the steam pools of {zone:1441} and defeat the {npc:216474} they call. {quest:96135} is an elite quest: grouping up is advised."] = "{npc:259023} дает вам {item:268582}: установите их у паровых озер ({zone:1441}) и победите того, кого они призовут: {npc:216474}. {quest:96135} – элитное задание: лучше собрать группу.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: ваш {item:5178}",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} стоит лагерем на востоке зоны {zone:1416}, к северо-востоку от места {area:272}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} и ваше оружие",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} и оружие Бури (Альянс)",
} end)()
