} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 очков репутации у Орды",
		["A {area:2057} fight at 60 for Horde reputation; Forever removed the {item:20134}."] = "Бой в подземелье {area:2057} на 60-м уровне ради репутации у Орды; в Forever убрали предмет {item:20134}.",
		["An {item:12800} comes from Thorium veins, a {item:18335} from the elites of the {zone:1422}, both rarely: buy them at the auction house if you can."] = "{item:12800} добывается из ториевых жил, {item:18335} — с элитных противников зоны {zone:1422}, оба редко: по возможности купите их на аукционе.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds."] = "На 58-м уровне {npc:13417}, учитель шаманов ({object:172957}), просит два редких алмаза.",
		["Two diamonds"] = "Два алмаза",
		["he hands you the {item:18746}"] = "он вручает вам {item:18746}",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. Use the {item:18746} in the heart of the {object:179746}'s basement, beat the spirits it calls, then {npc:14516}. All are elite: bring a group."] = "{area:2057} находится под местом {area:2298} — городком на острове на юго-востоке зоны {zone:1422}. Используйте {item:18746} в центре подвала Главного склепа, победите призванных духов, а затем: {npc:14516}. Все они элитные: возьмите группу.",
		["{quest:7668} needs level 60."] = "Для задания {quest:7668} нужен 60-й уровень.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, sends you to {npc:6176}."] = "На 50-м уровне {npc:13417}, учитель шаманов ({object:172957}), отправит вас сюда: {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "На 50-м уровне {npc:3032}, учитель шаманов ({zone:1456}), отправит вас сюда: {npc:6176}.",
		["Experience and gold"] = "Опыт и золото",
		["Experience and gold at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "Опыт и золото на 50-м уровне, финал – здесь: {area:1417}; в Forever убран выбор предметов из Classic.",
		["In the {zone:1422}, the Venom Mist Lurkers drop the {item:20610} and the Diseased Black Bears the {item:20611} (about one kill in five each)."] = "В зоне {zone:1422} {item:20610} падает с воронковых пауков Ядовитого Тумана, а {item:20611} – с больных черных медведей (примерно в одном случае из пяти).",
		["One each of {item:7069}, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house."] = "По одному: {item:7069}, огонь, земля и вода. Они падают с изгнанников Нагорья Арати, с каждого своя стихия, примерно в одном случае из десяти: грохочущие изгнанники (воздух), пылающие изгои (огонь), шумные изгнанники (земля) и морские изгои (вода). Или купите на аукционе.",
		["Spider eye and bear claw"] = "Паучий глаз и медвежий коготь",
		["The four elements"] = "Четыре стихии",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}) lies under the {area:74}; the arrow points at its entrance. Gasher or {npc:5716} drop the {item:20606}, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group."] = "{area:1417} ({area:1477}) находится под местом {area:74}; стрелка указывает на вход. {item:20606} падает с Ранокола или NPC {npc:5716}, синий – с Хукку или Миджана, зеленый – с Золо или Лоро: все шестеро – элитные тролли внутри. Соберите группу.",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: шумные изгнанники",
		["{item:7068}: Burning Exiles"] = "{item:7068}: пылающие изгои",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: грохочущие изгнанники",
		["{item:7070}: Cresting Exiles"] = "{item:7070}: морские изгои",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} стоит лагерем на востоке зоны {zone:1416}, к северо-востоку от места {area:272}.",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} и {quest:8413}",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "Редкое тканевое одеяние для 30-х уровней; {npc:6266} создает его из принесенных вами частей.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "На 31-м уровне {npc:3326} ({object:172960}) отправляет вас к персонажу {npc:6266} ({area:392}).",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "На 31-м уровне {npc:4563} ({object:36082}) отправляет вас к персонажу {npc:6266} ({area:392}). Дирижабль летит: {zone:1420} → {zone:1411}.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "На 31-м уровне {npc:461} ({object:2164}, {object:2101}) отправляет вас к персонажу {npc:6266} ({area:392}).",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "На 31-м уровне {npc:5172} ({zone:1455}) отправляет вас к персонажу {npc:6266} ({area:392}).",
		["Back to {npc:6266}"] = "Назад к {npc:6266}",
		["Back to {npc:6266} with the thread, the coal and a {item:6265}. Wait while she completes the robe, then speak to her again."] = "Вернитесь к {npc:6266} с нитью, углем и предметом {item:6265}. Подождите, пока она закончит одеяние, затем снова поговорите с ней.",
		["Bring {npc:6266} a {item:5770}: tailors sew it from a pattern that drops; otherwise buy one at the Auction House. Her next errand needs a {item:3577}: smelted from {item:2776}, or from the Auction House."] = "Принесите {npc:6266} предмет {item:5770}: портные шьют его по выкройке, которая падает с врагов; иначе купите на аукционе. Для следующего поручения нужен {item:3577}: выплавьте из предмета {item:2776} или купите на аукционе.",
		["The Burning Exiles, fire elementals in western {zone:1417}, drop the coal."] = "Уголь падает с пылающих изгоев – огненных элементалей на западе зоны {zone:1417}.",
		["The Hatefury satyrs of {area:603}, in north-eastern {zone:1443}, carry the blood; the Lesser Infernals of Mannoroc Coven, in the south, the stone."] = "Кровь носят сатиры из племени Ярой Ненависти ({area:603}, северо-восток зоны {zone:1443}), камень – младшие инферналы на юге (Поле Маннорок).",
		["Vials of Hatefury Blood"] = "Фиалы крови сатира из клана Ярой Ненависти",
		["Wait for the robe"] = "Дождитесь одеяния",
		["{npc:2670} in {area:35} has the thread for you."] = "У персонажа {npc:2670} ({area:35}) есть для вас нить.",
		["{npc:2670} sells tailoring supplies in {area:35}. Bring him the {item:3577}."] = "{npc:2670} продает товары для портных ({area:35}). Принесите ему: {item:3577}.",
		["{npc:6266} again"] = "Снова {npc:6266}",
		["{npc:6266} stands in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266} стоит в башне на холме над местом {area:392}, рядом с персонажем {npc:6251}.",
		["{zone:1443} demons"] = "Демоны: {zone:1443}",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
		["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "На 30-м уровне {npc:6120} ({object:32383}) отправит вас сюда: {npc:6251} ({area:392}).",
		["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "На 30-м уровне {npc:6122} (подвал: {object:2164}, {object:2101}) отправит вас сюда: {npc:6251} ({area:392}).",
		["Back to {npc:6251} in {area:392}. Use the {quest:1804} on the summoning circle beside him and defeat the felhunter to bind it."] = "Назад: {npc:6251} ({area:392}). Используйте {quest:1804} на круге призыва рядом с ним и победите охотника Скверны, чтобы подчинить его.",
		["Felhunter (Alliance)"] = "Охотник Скверны (Альянс)",
		["Rods of Channeling"] = "Жезлы направления",
		["The Dragonmaw Bonewarders and Shadowwarders hold the hills east of the road through the {zone:1437}: the rods drop from them."] = "Костостражи и хранители теней из клана Драконьей Пасти занимают холмы к востоку от дороги через зону {zone:1437}: жезлы падают с них.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Охотник Скверны – демон против заклинателей, а также {item:22244} для ваших осколков.",
		["The {item:6931} lies on the shore west of {area:271}, past the Torn Fin murloc camps."] = "{item:6931} лежит на берегу к западу (ориентир: {area:271}), за лагерями мурлоков из племени Рваного Плавника.",
		["The {object:92423} lies in the canyon north of {area:484}."] = "{object:92423} лежит в ущелье к северу (ориентир: {area:484}).",
		["{area:392} is on the {zone:1413} coast; {npc:6251} stands on the hill in town."] = "{area:392} – на побережье зоны {zone:1413}; {npc:6251} стоит на холме в городе.",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, внутри: {object:92423}",
		["{npc:6251}: he binds the felhunter to you"] = "{npc:6251}: он привяжет к вам охотника Скверны",
		["{npc:6294} stands in the {object:32356}."] = "{npc:6294} стоит здесь: {object:32356}.",
} end)()
