		["{npc:13442}: Crystal Cluster"] = "{npc:13442}: Гроздь кристаллов",
} end)()
t.guides["forever/reputation/arathi-basin"] = (function() return {
		["Arathi Basin Reputation"] = "Репутация: Низина Арати",
		["Exalted with the League of Arathor earns a Legacy Point."] = "Превознесение у Лиги Аратора дает очко наследия.",
		["Exalted with {faction:510} earns a Legacy Point."] = "Превознесение у фракции {faction:510} дает очко наследия.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15350} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Продолжайте играть: {zone:1461}. В выходные «К оружию!» ({zone:1461}) {npc:15350} в столицах принимает три почетных знака Низины Арати за дополнительную репутацию.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15351} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Продолжайте играть: {zone:1461}. В выходные «К оружию!» ({zone:1461}) {npc:15351} в столицах принимает три почетных знака Низины Арати за дополнительную репутацию.",
		["Keep playing {zone:1461}; wins with many bases held pay the most."] = "Продолжайте играть: {zone:1461}; больше всего дают победы с множеством удержанных баз.",
		["League of Arathor to Exalted"] = "Лига Аратора до уровня «Превознесение»",
		["League of Arathor to Friendly"] = "Лига Аратора до уровня «Дружелюбие»",
		["League of Arathor to Honored"] = "Лига Аратора до уровня «Уважение»",
		["League of Arathor to Revered"] = "Лига Аратора до уровня «Почтение»",
		["{faction:509} fights for {zone:1461} from {area:320}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:509} сражается за зону {zone:1461}, база – {area:320}. Репутацию дает поле боя: ресурсы, собранные командой, приносят ее всем, так что чем больше баз и дольше, тем больше репутации. Встаньте в очередь у любого военачальника поля боя. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{faction:510} fight for {zone:1461} from {area:321}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:510} сражаются за зону {zone:1461}, база – {area:321}. Репутацию дает поле боя: ресурсы, собранные командой, приносят ее всем, так что чем больше баз и дольше, тем больше репутации. Встаньте в очередь у любого военачальника поля боя. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{faction:510} to Exalted"] = "{faction:510} до уровня «Превознесение»",
		["{faction:510} to Friendly"] = "{faction:510} до уровня «Дружелюбие»",
		["{faction:510} to Honored"] = "{faction:510} до уровня «Уважение»",
		["{faction:510} to Revered"] = "{faction:510} до уровня «Почтение»",
		["{npc:14983}'s The Battle for {zone:1461}! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; {npc:14984} beside him takes Arathi Resource Crates."] = "Задания от NPC {npc:14983} – «Битва за Низину Арати» ({zone:1461}; атакуйте каждую базу) и «Контроль над четырьмя базами» / «Контроль над пятью базами» – одноразовые; {npc:14984} рядом с ним принимает: {item:19725}.",
		["{npc:15021}'s The Battle for {zone:1461}! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; {npc:15022} beside him takes Arathi Resource Crates."] = "Задания от NPC {npc:15021} – «Битва за Низину Арати» ({zone:1461}; атакуйте каждую базу) и «Захват четырех баз» / «Занять пять баз» – одноразовые; {npc:15022} рядом с ним принимает: {item:19725}.",
		["{npc:15126} hands out one Defiler's care package by level"] = "{npc:15126} выдает по одному полевому комплекту Осквернителей за уровень",
		["{npc:15127} hands out one Arathor care package by level"] = "{npc:15127} выдает по одному полевому комплекту Лиги Аратора за уровень",
} end)()
t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "Репутация: Серебряный Рассвет",
		["Corruptor's Scourgestones and dungeons to Revered"] = "Камни осквернителей Плети ({item:12843}) и подземелья до уровня «Почтение»",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "Адепты Тьмы ({npc:8546}) и темные маги (уровень 58-60) роняют здесь {item:12841}, а также камни приспешников и {item:14047}. Сдавайте камни захватчиков по 10, а камни приспешников по 20: {npc:11039} – {area:2268}. В Classic и те и другие перестают давать репутацию на уровне «Уважение».",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "С уровня «Уважение» репутацию дают {item:12843} (по одному за сдачу) и убийства Плети: {area:2279} и {area:2057}. Камни осквернителей падают с боссов Плети там ({npc:1853}, {npc:10433}, Вектус), а также с NPC {npc:1852} и Гнилиуса (зона {zone:1422}). Многократные походы в подземелья окупаются быстрее любого фарма в открытом мире.",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:152}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "Вурдалаки и скелеты по всей зоне {zone:1422} примерно в половине случаев роняют: {item:12840}; здесь они встречаются густо. Сдавайте по 20 любому офицеру Серебряного Рассвета (Чистосердая – {area:3197}, Гаруш – {area:152}, {npc:11039} – {area:2268}). Каждая сдача также дает {item:12844} для интендантов Серебряного Рассвета.",
		["Invader's Scourgestones to Honored"] = "Камни захватчиков Плети ({item:12841}) до уровня «Уважение»",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "Проходите {area:2279} и {area:2057} и сдавайте каждый {item:12843} ({area:2268}) до превознесения.",
		["Minion's Scourgestones to Friendly"] = "Камни приспешников Плети ({item:12840}) до уровня «Дружелюбие»",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "Проходите {area:2279} (обе части) и {area:2057}, убивая всю Плеть на пути.",
		["{faction:529} to Exalted"] = "{faction:529} до уровня «Превознесение»",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:152} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}: начальная репутация – равнодушие. Возьмите жетон у NPC {npc:10839} ({area:152}) и наденьте: в Classic камни Плети падают, только пока надет аксессуар {quest:5401}. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}: начальная репутация – равнодушие. Возьмите жетон у NPC {npc:10840} ({area:3197}) и наденьте: в Classic камни Плети падают, только пока надет аксессуар {quest:5401}. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{quest:5401} (Alliance)"] = "{quest:5401} (Альянс)",
		["{quest:5401} (Horde)"] = "{quest:5401} (Орда)",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "{item:20513}, {item:20514} и {item:20515} можно сдавать NPC {npc:15306} повторно после вводных заданий.",
		["Back to {area:3425}"] = "Вернитесь: {area:3425}",
		["Cenarion Circle Reputation"] = "Репутация: Круг Кенария",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "Задание с текстами повторяется: {npc:15306} принимает: {item:20404} – снова и снова. Фармите их в лагерях культистов.",
		["Encrypted Twilight Texts to Friendly"] = "Зашифрованные тексты Сумеречных ({item:20404}) до уровня «Дружелюбие»",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "Дальше основную репутацию дают рейд {area:3454} и сдача знаков Совета Бездны (талисманы, перстни, скипетры).",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "Продолжайте фармить лагеря Сумеречного Молота. В облачении культиста Сумеречного Молота и со станционным медальоном (задание «Станционный медальон» от NPC {npc:15282}) можно призывать храмовников у камней ветра ({object:180461}); {item:20513} с них сдавайте NPC {npc:15306}.",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "Проходите {area:3454} и сдавайте знаки Совета Бездны до превознесения.",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "Культисты Сумеречного Молота занимают лагеря на западе зоны {zone:1451}. Здесь вперемешку геолорды ({quest:8320}) и камнезовы; с любого культиста может упасть {item:20404}. Каждое убийство культиста также дает репутацию ({faction:609}). Геолорды засчитываются для задания {quest:8320}, только если вам 60 и вы его взяли.",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425} – обнесенный стеной городок в центре севера зоны {zone:1451}. Бор и {npc:15270} стоят внутри рядом. {faction:609}: начальная репутация – равнодушие. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{faction:609} to Exalted"] = "{faction:609} до уровня «Превознесение»",
		["{faction:609} to Honored"] = "{faction:609} до уровня «Уважение»",
		["{faction:609} to Revered"] = "{faction:609} до уровня «Почтение»",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}: {item:20404}",
		["{quest:8320} needs level 60"] = "{quest:8320}: нужен 60-й уровень",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Адепты Тьмы и темные маги (уровень 58-60) роняют его здесь; каждое убийство Плети здесь также идет в зачет фракции {object:92525} (см. тот гайд). Также можно купить на аукционе.",
		["Darkspear Trolls Reputation"] = "Репутация: Племя Черного Копья",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Огры из клана Песчаного Молота (уровень 45-48) роняют ее здесь. Также можно купить на аукционе.",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Продолжайте сдавать {quest:7837}, пока репутация ({faction:530}) не достигнет превознесения. {item:14047}: адепты Тьмы и темные маги (уровень 58-60) в зоне {zone:1423} или аукцион.",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Продолжайте сдавать {quest:7837}, по 20 шт. {item:14047}. {item:14047}: адепты Тьмы и темные маги (уровень 58-60) в зоне {zone:1423} или аукцион.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Кентавры из племени Колкар (уровень 30-33) роняют его здесь. Также можно купить на аукционе.",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "Головорезы Торговой компании в месте {area:381} (уровень 16-17) роняют ее здесь. Также можно купить на аукционе.",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727} принимает ткань для фракции {faction:530} ({object:172961}, {zone:1454}). Первые пожертвования шерсти, шелкового материала, магической ткани и предмета {item:14047} (по 60 штук) делаются один раз и дают больше всего репутации за единицу ткани; после них {quest:7837} повторяется до превознесения. Превознесение у города другой расы позволяет покупать ее транспорт. Бонус наследия Forever «Дипломат» увеличивает получаемую репутацию.",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727}: {item:14047} сдан",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837}: 20 шт. {item:14047} за раз, повторяется сколько угодно. Приносите {item:14047} партиями по 20 и сдавайте все сразу, раз за разом. {item:14047}: адепты Тьмы и темные маги (уровень 58-60) в зоне {zone:1423} или аукцион.",
		["{quest:7837} to Exalted"] = "{quest:7837} — до превознесения",
		["{quest:7837} to Honored"] = "{quest:7837} — до уважения",
		["{quest:7837} to Revered"] = "{quest:7837} — до почтения",
} end)()
t.guides["forever/reputation/darnassus"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Добыча здесь: адепты Тьмы ({npc:8546}) и темные маги (уровень 58-60); каждое убийство Плети здесь также дает репутацию ({object:92525}, см. тот гайд). Подойдет и аукцион.",
		["Darnassus Reputation"] = "Репутация: Дарнасс",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Добыча здесь: огры из клана Песчаного Молота (уровень 45-48). Подойдет и аукцион.",
		["Keep handing in {quest:7801} until {faction:69} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Сдавайте задание {quest:7801}, пока репутация ({faction:69}) не дойдет до превознесения. {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["Keep handing in {quest:7801}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Продолжайте сдавать: {quest:7801}, по 20 шт. ({item:14047}). {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["Riverpaw Bandits and Taskmasters (level 16-18) drop it here. The Auction House works too."] = "Добыча здесь: бандиты ({npc:452}) и надсмотрщики из стаи Речной Лапы (уровень 16-18). Подойдет и аукцион.",
		["Syndicate Mercenaries at Stromgarde (level 31-32) drop it here. The Auction House works too."] = "Добыча здесь: наемники Синдиката у Стромгарда (уровень 31-32). Подойдет и аукцион.",
		["{npc:14725} takes cloth for {faction:69} in {faction:69}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7801} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14725} принимает ткань для фракции {faction:69} (место: {faction:69}). Первые пожертвования шерсти, шелкового материала, магической ткани и предмета {item:14047} (по 60 шт.) делаются один раз и дают больше всего репутации за ткань; после них {quest:7801} повторяется до превознесения. Превознесение у города другой расы позволяет покупать транспорт этой расы. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{npc:14725}: {item:14047} delivered"] = "{npc:14725}: {item:14047} сдано",
		["{quest:7801} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7801}: 20 шт. ({item:14047}) за сдачу, повторяется сколько угодно. Приносите {item:14047} партиями по 20 и сдавайте все сразу, одну сдачу за другой. {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["{quest:7801} to Exalted"] = "{quest:7801} до уровня «Превознесение»",
		["{quest:7801} to Honored"] = "{quest:7801} до уровня «Уважение»",
		["{quest:7801} to Revered"] = "{quest:7801} до уровня «Почтение»",
} end)()
t.guides["forever/reputation/gnomeregan-exiles"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Добыча здесь: адепты Тьмы ({npc:8546}) и темные маги (уровень 58-60); каждое убийство Плети здесь также дает репутацию ({object:92525}, см. тот гайд). Подойдет и аукцион.",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Добыча здесь: огры из клана Песчаного Молота (уровень 45-48). Подойдет и аукцион.",
		["Gnomeregan Exiles Reputation"] = "Репутация: Изгнанники Гномрегана",
		["Keep handing in {quest:7812} until {faction:54} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Сдавайте задание {quest:7812}, пока репутация ({faction:54}) не дойдет до превознесения. {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["Keep handing in {quest:7812}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Продолжайте сдавать: {quest:7812}, по 20 шт. ({item:14047}). {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["Riverpaw Bandits and Taskmasters (level 16-18) drop it here. The Auction House works too."] = "Добыча здесь: бандиты ({npc:452}) и надсмотрщики из стаи Речной Лапы (уровень 16-18). Подойдет и аукцион.",
		["Syndicate Mercenaries at Stromgarde (level 31-32) drop it here. The Auction House works too."] = "Добыча здесь: наемники Синдиката у Стромгарда (уровень 31-32). Подойдет и аукцион.",
		["{npc:14724} takes cloth for {faction:54} in {object:171524}, {zone:1455}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7812} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14724} принимает ткань для фракции {faction:54} (место: {object:171524}, {zone:1455}). Первые пожертвования шерсти, шелкового материала, магической ткани и предмета {item:14047} (по 60 шт.) делаются один раз и дают больше всего репутации за ткань; после них {quest:7812} повторяется до превознесения. Превознесение у города другой расы позволяет покупать транспорт этой расы. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{npc:14724}: {item:14047} delivered"] = "{npc:14724}: {item:14047} сдано",
		["{quest:7812} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7812}: 20 шт. ({item:14047}) за сдачу, повторяется сколько угодно. Приносите {item:14047} партиями по 20 и сдавайте все сразу, одну сдачу за другой. {item:14047}: Адепты Тьмы и темные маги (уровень 58-60) – зона {zone:1423}, или аукцион.",
		["{quest:7812} to Exalted"] = "{quest:7812} до уровня «Превознесение»",
		["{quest:7812} to Honored"] = "{quest:7812} до уровня «Уважение»",
		["{quest:7812} to Revered"] = "{quest:7812} до уровня «Почтение»",
} end)()
t.guides["forever/reputation/hydraxian-waterlords"] = (function() return {
		["Back to {npc:13278}"] = "Вернитесь к NPC {npc:13278}",
		["Both elementals roam north-western {zone:1451}; the Rumblers cluster a little further north."] = "Оба вида элементалей бродят на северо-западе зоны {zone:1451}; грохотуны держатся чуть севернее.",
		["Bring the Hands of Lucifron, Gehennas, Shazzrah and Sulfuron from the {area:2717}."] = "Принесите из рейда ({area:2717}) руки Люцифрона, Гееннаса, Шаззраха и Сульфурона.",
		["Dust Stormers and Desert Rumblers"] = "Пылевихри ({npc:11744}) и пустынные грохотуны ({npc:11746})",
		["Hydraxian Waterlords Reputation"] = "Репутация: Гидраксианские Повелители Вод",
		["Keep clearing the {area:2717} until Exalted."] = "Зачищайте {area:2717} до превознесения.",
		["Kill a {npc:11668}, a {npc:11658}, an {npc:11673} and a {npc:12101} in the {area:2717}. Every {area:2717} elemental and boss also counts toward the Waterlords."] = "Убейте по одному: {npc:11668}, {npc:11658}, {npc:11673} и {npc:12101} ({area:2717}). Каждый элементаль и босс ({area:2717}) также дает репутацию у Повелителей Вод.",
		["Use the {item:17310} on the poisoned water elementals of {zone:1423}, then loot their {item:17309} (12)."] = "Используйте {item:17310} на отравленных водных элементалях (зона {zone:1423}), затем заберите с них: {item:17309} (12).",
		["{area:2717} clears carry the rest. Bosses always count; in Classic, trash kills stop giving Waterlords reputation partway up, so late on the bosses do the work."] = "Остальное дают зачистки ({area:2717}). Боссы засчитываются всегда; в Classic обычные противники на полпути перестают давать репутацию Повелителей Вод, так что под конец ее приносят боссы.",
		["{faction:749} to Exalted"] = "{faction:749} до уровня «Превознесение»",
		["{faction:749} to Revered"] = "{faction:749} до уровня «Почтение»",
		["{npc:13278} stands on a small island off the eastern coast of {zone:1447}; swim or walk the shallows out to him. The {faction:749} start out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:13278} стоит на маленьком острове у восточного побережья зоны {zone:1447}; доплывите или дойдите по отмели. {faction:749}: начальная репутация – равнодушие. Бонус наследия Forever «Дипломат» ускоряет рост репутации.",
		["{npc:9816} in Upper Blackrock Spire drops the {quest:6821}. This needs a raid group."] = "{npc:9816} в верхней части Вершины Черной горы роняет предмет для задания {quest:6821}. Нужна рейдовая группа.",
		["{quest:6823} needs Honored. At Honored, {npc:13278} hands out {item:17333}, used to douse the runes in the {area:2717} that summon {npc:12018}; at Revered, the reusable {item:22754}."] = "{quest:6823}: нужно «Уважение». На уровне «Уважение» {npc:13278} выдает {item:17333} – им гасят руны ({area:2717}), чтобы призвать босса ({npc:12018}); на уровне «Почтение» – многоразовую: {item:22754}.",
} end)()
t.guides["forever/reputation/ironforge"] = (function() return {
